#!/usr/bin/env bash
#
# Installs layers' kernel modules into a rootfs overlay.
#
# Usage: install-modules.sh <system dir> <devkit> <rootfs overlay> <layer>=<modules dir>...
#
# Modules go to /lib/modules/<release>/updates/<layer>/, and the module index
# (modules.dep, modules.alias, ...) is regenerated by depmod over the
# system's module tree plus every layer's modules, so modprobe and uevent
# autoloading find them. depmod -e runs against the dev kit's
# Module.symvers: a module the kernel would refuse fails here instead of at
# boot.

set -euo pipefail

SCRIPTS=$(dirname "$(realpath "$0")")
source "$SCRIPTS/lib.sh"

[[ $# -ge 4 ]] || die "usage: install-modules.sh <system dir> <devkit> <rootfs overlay> <layer>=<modules dir>..."
SYSTEM_DIR=$1 DEVKIT=$2 OVERLAY=$3
shift 3

RELEASE=$(devkit_env "$DEVKIT" KERNEL_RELEASE)
ROOT=$(mktemp -d)
trap 'rm -rf "$ROOT"' EXIT
TREE="$ROOT/lib/modules/$RELEASE"

if [[ -f $SYSTEM_DIR/images/rootfs.tar ]]; then
    tar -x -f "$SYSTEM_DIR/images/rootfs.tar" -C "$ROOT" --wildcards "*lib/modules/$RELEASE*"
else
    unsquashfs -q -f -d "$ROOT" "$SYSTEM_DIR/images/rootfs.squashfs" "/lib/modules/$RELEASE" > /dev/null
fi
[[ -d $TREE ]] || die "the system's root filesystem has no /lib/modules/$RELEASE"

for layer in "$@"; do
    name=${layer%%=*}
    dir=${layer#*=}
    mkdir -p "$TREE/updates/$name"
    cp "$dir"/*.ko "$TREE/updates/$name/"
    for ko in "$TREE/updates/$name"/*.ko; do
        echo "nerves_layer: /lib/modules/$RELEASE/updates/$name/$(basename "$ko")" >&2
    done
done

# An empty config directory keeps the build host's /etc/depmod.d out of the
# generated index.
mkdir -p "$ROOT/depmod.d"
PROBLEMS=$(depmod -b "$ROOT" -C "$ROOT/depmod.d" -e -E "$DEVKIT/Module.symvers" "$RELEASE" 2>&1 |
    grep -E 'unknown symbol|disagrees about version' || true)
[[ -z $PROBLEMS ]] || die "depmod found modules the system kernel won't load:
$PROBLEMS"

rm -rf "${OVERLAY:?}/lib/modules/$RELEASE"
mkdir -p "$OVERLAY/lib/modules/$RELEASE"
cp -r "$TREE/updates" "$TREE"/modules.* "$OVERLAY/lib/modules/$RELEASE/"
